import React, { useState } from "react";
import { Link } from "react-router-dom";
import "./AdminB.css";

export default function AdminB() {
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [username, setUsername] = useState("");
  const [password, setPassword] = useState("");
  const [error, setError] = useState("");

  const handleLogin = (e) => {
    e.preventDefault();
    if (!username.trim() || !password.trim()) {
      setError("Por favor, completa todos los campos.");
      return;
    }
    setError("");
    setIsLoggedIn(true);
  };

  if (!isLoggedIn) {
    return (
      <div className="admin-container">
        <header className="admin-header">
          <div className="header-content">
            <h1 className="header-title">TalkinPon</h1>
            <div className="header-center-text">
              <span>Inicio de sesión.</span>
            </div>
            <Link to="/">
              <img
                src="/logo-app.png"
                alt="Logo"
                className="header-logo"
              />
            </Link>
          </div>
        </header>

        <main className="login-main">
          <div className="login-card">
            <h2 className="login-title">Bienvenido Administrador</h2>

            <form onSubmit={handleLogin} className="login-form">
              <div className="form-group">
                <label htmlFor="username">Usuario:</label>
                <input
                  type="text"
                  id="username"
                  value={username}
                  onChange={(e) => {
                    setUsername(e.target.value);
                    setError("");
                  }}
                  placeholder="Ingresa tu usuario..."
                  required
                />
              </div>

              <div className="form-group">
                <label htmlFor="password">Contraseña:</label>
                <input
                  type="password"
                  id="password"
                  value={password}
                  onChange={(e) => {
                    setPassword(e.target.value);
                    setError("");
                  }}
                  placeholder="Ingresa tu contraseña..."
                  required
                />
              </div>

              {error && <div className="error-message">{error}</div>}

              <button type="submit" className="login-button">
                Iniciar sesión
              </button>
            </form>
          </div>
        </main>
      </div>
    );
  }

  return (
    <div className="admin-container">
      <header className="admin-header">
        <div className="header-content">
          <h1 className="header-title">TalkinPon - Panel de Administrador</h1>
          <div className="header-buttons">
            <button onClick={() => setIsLoggedIn(false)} className="logout-btn">
              Cerrar sesión
            </button>
            <Link to="/">
              <img
                src="/university-logo-circular.jpg"
                alt="Logo"
                className="header-logo"
              />
            </Link>
          </div>
        </div>
      </header>

      <main className="admin-main">
        <div className="admin-card">
          <h2 className="admin-welcome">
            Bienvenido al Panel de Administración, {username}
          </h2>

          <div className="admin-options">
            <div className="admin-option">
              <h3>Gestión de Usuarios</h3>
              <p>Administrar usuarios del sistema</p>
            </div>

            <div className="admin-option">
              <h3>Configuración</h3>
              <p>Ajustes del sistema</p>
            </div>

            <div className="admin-option">
              <h3>Reportes</h3>
              <p>Ver estadísticas y reportes</p>
            </div>
          </div>
        </div>
      </main>
    </div>
  );
}
